<?php
function negative_exception_open($platform,$pid,$before,$after,$ref,$date){if(!process_ready()||$after>=0)return;db()->prepare('INSERT INTO stock_exceptions(product_id,platform,reference_no,txn_date,before_qty,after_qty,opened_by) VALUES(?,?,?,?,?,?,?)')->execute([$pid,$platform,$ref,$date,$before,$after,current_user()['id']]);}
function negative_exception_assign($id,$uid,$reason){if(current_user()['role']!=='Admin')throw new Exception('Administrator assignment required.');$reason=process_reason($reason);$q=db()->prepare("SELECT role FROM users WHERE id=? AND active=1 AND approval_status='Approved'");$q->execute([$uid]);$ownerRole=$q->fetchColumn();if(!$ownerRole||!can_role_action($ownerRole,'negative_resolve'))throw new Exception('Select an active Admin or Inventory Controller.');db()->prepare("UPDATE stock_exceptions SET assigned_to=?,reason=? WHERE id=? AND status='Open'")->execute([$uid,$reason,$id]);audit('Assign negative stock exception','Exception',(string)$id,'Owner '.$uid.'; '.$reason);}
function negative_exception_resolve($id,$reason,$reference){return process_transaction(function()use($id,$reason,$reference){$reason=process_reason($reason);$reference=trim($reference);$q=db()->prepare("SELECT * FROM stock_exceptions WHERE id=? AND status='Open' FOR UPDATE");$q->execute([$id]);$r=$q->fetch();if(!$r)throw new Exception('Exception is no longer open.');if(current_user()['role']!=='Admin'&&(int)$r['assigned_to']!==current_user()['id'])throw new Exception('Only the assigned owner or Admin can resolve this exception.');db()->prepare('SELECT id FROM products WHERE id=? FOR UPDATE')->execute([$r['product_id']]);if(platform_qty($r['platform'],$r['product_id'])<0||stock_row($r['product_id'])['current']<0)throw new Exception('The stock is still negative. Post the reviewed correction or received stock first.');
 $proof=db()->prepare('SELECT COUNT(*) FROM (SELECT reference_no ref,product_id,created_at FROM inflows UNION ALL SELECT order_id ref,product_id,created_at FROM outflows UNION ALL SELECT transfer_ref ref,product_id,created_at FROM platform_transfers) t WHERE ref=? AND product_id=? AND created_at>=?');$proof->execute([$reference,$r['product_id'],$r['created_at']]);if(!$proof->fetchColumn())throw new Exception('Enter a posted correction reference for this product from after the exception was opened.');db()->prepare("UPDATE stock_exceptions SET status='Resolved',reason=?,correction_reference=?,resolved_by=?,resolved_at=NOW() WHERE id=?")->execute([$reason,$reference,current_user()['id'],$id]);audit('Resolve negative stock exception','Exception',(string)$id,$reason.'; correction '.$reference);});}
